alter table public.boards enable row level security;
alter table public.board_members enable row level security;
alter table public.cards enable row level security;

create or replace function public.is_board_member(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.board_members m
    where m.board_id = p_board_id
      and m.user_id = auth.uid()
  );
$$;

create or replace function public.is_board_editor(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.board_members m
    where m.board_id = p_board_id
      and m.user_id = auth.uid()
      and m.role = 'editor'
  );
$$;

create or replace function public.board_is_archived(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.boards b
    where b.id = p_board_id
      and b.is_archived = true
  );
$$;

create or replace function public.can_write_to_board(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.board_members m
    where m.board_id = p_board_id
      and m.user_id = auth.uid()
      and m.role = 'editor'
      and not public.board_is_archived(p_board_id)
  );
$$;

create or replace function public.enforce_card_board_security()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.board_id is distinct from old.board_id then
    if not public.is_board_editor(new.board_id) then
      raise exception 'card can only be moved to a board where the user is an editor';
    end if;
  end if;

  if new.assignee_id is distinct from old.assignee_id then
    if not public.is_board_editor(new.board_id) then
      raise exception 'card can only be assigned to a board where the user is an editor';
    end if;
  end if;

  return new;
end;
$$;

create trigger enforce_card_board_security
before insert or update on public.cards
for each row execute function public.enforce_card_board_security();

create policy "board_members_select_own_boards"
on public.boards
for select
to authenticated
using (public.is_board_member(id));

create policy "cards_select_own_boards"
on public.cards
for select
to authenticated
using (public.is_board_member(board_id));

create policy "cards_insert_own_editor_boards"
on public.cards
for insert
to authenticated
with check (public.can_write_to_board(board_id));

create policy "cards_update_own_editor_boards"
on public.cards
for update
to authenticated
using (public.can_write_to_board(board_id))
with check (public.can_write_to_board(board_id));

create policy "cards_delete_own_editor_boards"
on public.cards
for delete
to authenticated
using (public.can_write_to_board(board_id));

create policy "board_members_select_own_boards"
on public.board_members
for select
to authenticated
using (user_id = auth.uid() or public.is_board_member(board_id));

revoke all on public.boards from anon, authenticated;
revoke all on public.board_members from anon, authenticated;
revoke all on public.cards from anon, authenticated;

