create or replace function public.prevent_request_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' or current_user = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.unit_id is distinct from old.unit_id
     or new.created_by is distinct from old.created_by
     or new.description is distinct from old.description then
    raise exception 'Only request status can be updated';
  end if;

  if new.status is distinct from old.status then
    if old.status not in ('open', 'in_progress') then
      raise exception 'Cannot change status of a done request';
    end if;
    if new.status not in ('in_progress', 'done') then
      raise exception 'Invalid status transition';
    end if;
  end if;

  return new;
end;
$$;

